foreach ($cases as $category => $messages) {
    foreach ($messages as $messageIndex => $message) {
        foreach ($contexts as $contextIndex => $context) {
            $id = sprintf('%s-%d-%d', $category, $messageIndex + 1, $contextIndex + 1);
            $input = ['message' => $message, 'context' => $context, 'followup' => 'Проверь актуальность, права и источник перед ответом.', 'request_id' => sprintf('00000000-0000-4000-8000-%012d', count($scenarios) + 1)];
